UPDATE public.courses SET axes = $ax46$["بيوت الثقافة وأهدافها ودورها الثقافي في المجتمع.","تأثير بيوت الثقافة في التنمية الثقافية والاجتماعية.","دور المسرح، والسينما، والفنون، والحرف اليدوية في نشر الثقافة.","مفهوم الهوية الثقافية ومقوماتها ونظرياتها.","سمات الإدارة الناجحة في بيوت الثقافة وعناصرها.","التخطيط الإستراتيجي وأولويات بيوت الثقافة وقياس نجاح الخطط.","مفهوم الجودة الشاملة وتطبيقاتها في بيوت الثقافة.","إستراتيجيات إدارة الكوادر البشرية وتطوير المهارات في بيئات الثقافة.","مفهوم الملكية الفكرية، وحقوق المؤلف، وآليات حماية الملكية الفكرية في المملكة.","أسس التسويق الثقافي وإستراتيجياته وكتابة المحتوى التسويقي الثقافي."]$ax46$::jsonb WHERE trim(title) ILIKE '%بيوت الثقافة%';

UPDATE public.courses SET axes = $ax47$["مفهوم المبيعات الهاتفية وأهميتها.","مهارات التواصل الفعال والاستماع النشط لفهم احتياجات العملاء.","مهارات الإقناع والتأثير أثناء المكالمات الهاتفية.","إدارة الوقت وتنظيم الجداول اليومية لتقليل الوقت المهدر.","التخطيط المسبق ومعرفة الجمهور المستهدف.","صياغة السيناريوهات البيعية بكفاءة.","مهارة بناء الثقة مع العملاء في بداية المكالمات.","تحليل احتياجات العميل وتقديم حلول تلبي توقعاته.","التعامل مع الاعتراضات البيعية بفعالية وإغلاق الصفقات بنجاح.","بناء علاقات طويلة المدى مع العملاء وتعزيز الولاء.","استخدام أدوات التكنولوجيا، مثل: برامج إدارة علاقات العملاء (CRM)، وتقنيات تحليل الأداء؛ لتحسين النتائج.","مهارة التعامل مع أنماط العملاء المختلفة وتلبية احتياجاتهم بمرونة."]$ax47$::jsonb WHERE trim(title) ILIKE '%المبيعات الهاتفية%';

UPDATE public.courses SET axes = $ax48$["مفاهيم السكن والفرق بين المسكن والمبنى وأهمية السكن.","الحق في السكن اللائق وفقا لقانون حقوق الإنسان.","أنواع السكن واحتياجات السكن.","مفهوم السكن الجماعي وبرنامج السكن الجماعي للافراد في المملكة.","تصنيف السكن الجماعي ومهام مشرف السكن الجماعي.","الشروط الصحية والفنية والسلامة اللازمة في السكن الجماعي.","متطلبات إصدار ترخيص السكن الجماعي والتنظيم المكاني والفني والمعماري.","متطلبات الوقاية والحماية من الحرائق في السكن الجماعي.","لائحة المخالفات والغرامات الخاصة بالمراقبة والمتابعة في السكن الجماعي.","تطبيق المهارات الإدارية، والقيادية، والتقنية لمشرف السكن الجماعي بما يشمل التواصل، والصحة والسلامة، والصيانة، والأمن."]$ax48$::jsonb WHERE trim(title) ILIKE '%السكن الجماعي%';

UPDATE public.courses SET axes = $ax49$["تصنيف الفئات المختلفة من المنتجات الصحية والمكملات الغذائية حسب نوع الاستخدام والفئة المستهدفة.","تحليل آليات عمل منتجات إنقاص الوزن وحوارق الدهون من خلال فهم المكونات النشطة وتأثيرها الفسيولوجي.","أنواع مكملات البروتين والأحماض الأمينية، وتحديد المناسب منها لكل هدف صحي أو رياضي.","مكونات الغذاء الأساسية وعلاقتها بالصحة العامة واحتياجات الجسم اليومي.","مبادئ التغذية الصحية في إدارة الوزن من خلال بناء نظام غذائي متوازن يدعم فقدان الدهون دون التأثير في الصحة","مهارات التواصل الفعال بالعملاء والزملاء من خلال فهم عناصر التواصل اللفظي وغير اللفظي.","توظيف ما تم تعلمه في مواقف عملية واقعية من خلال أنشطة تطبيقية تحاكي بيئة العمل.","الاحترافية والشفافية والجودة في تقديم المشورة الغذائية والبيع المسؤول.","تمكين المتدربين من إعداد حلول واستشارات مخصصة لكل عميل بناء على فهم دقيق لاحتياجاته وسلوكياته الشرائية."]$ax49$::jsonb WHERE trim(title) ILIKE '%التغذية واللياقة%';

SELECT title, jsonb_array_length(axes) AS num_axes FROM public.courses WHERE is_active = true ORDER BY title;